import os
from ute_btssm import builder
from ute_btssm.btssm import BTSSM
from ute_btssm import scfc
import logging


class BaseSession(object):
    def __init__(self, alias, config, timeout):
        self._log = logging.getLogger(__name__)
        self._alias = alias
        self._config = config
        self._timeout = timeout
        self.session = None

    def _create_btssm_cmd_builder(self):
        return builder.BTSSMCommandBuilder(self._config.install_location)

    def _create_cl_cmd_builder(self, executor):
        return builder.CommandLineToolCommandBuilder(self._config.ssh_connection_params['host'], executor, self._config.jars_path)

    def _create_trs_cmd_builder(self, executor):
        trs_jars_path = '"{}{}{}"'.format(self._config.install_location, os.path.sep, os.path.join("tools", "TRSCommandLineTools", "lib"))
        return builder.TRSCommandBuilder(self._config.ssh_connection_params['host'], executor, trs_jars_path)

    def _create_temp_dir(self, executor):
        temp_dir = os.path.join('/tmp', 'ute_btssm_{}'.format(self._alias))
        executor.run_ignoring_rc('rm -rf {}'.format(temp_dir))
        executor.run('mkdir -p {}'.format(temp_dir))
        return temp_dir + os.path.sep

    def _remove_temp_dir(self):
        self.session.executor.run_ignoring_rc('rm -rf {}'.format(self.session.temp_dir))

    def _disconnect_executor(self):
        self.session.executor.disconnect()

    def _calculate_timeout(self):
        if self._timeout is None:
            return self._config.timeout
        return self._timeout + 30

    def _create_btssm(self, executor, temp_path):
        return BTSSM(executor, self._config.install_location, temp_path)

    def _create_scfc_validator(self, executor, btssm_cmd_builder, temp_path):
        return scfc.SCFCValidator(executor, btssm_cmd_builder, temp_path)

    def _create_scfc_fixer(self, btssm_cmd_builder):
        return scfc.SCFCFixer(btssm_cmd_builder)

    def _get_install_location(self, executor):
        out = executor.run("awk -F= /^BTS_SITE_MANAGER_INSTALL_PATH=/'{print $2}' /etc/profile | tail -1")
        return out.strip().replace("\\", "")


class Session(object):
    def __init__(self, log_path, btssm_cmd_builder, cl_cmd_builder, trs_cmd_builder, executor, btssm, temp_dir, scfc_validator, scfc_fixer, trs_ip):
        self.cmd_builder = _SessionCmdBuilder(btssm_cmd_builder, cl_cmd_builder, trs_cmd_builder)
        self.executor = executor
        self.temp_dir = temp_dir
        self.btssm = btssm
        self.scfc = _SessionScfc(scfc_validator, scfc_fixer)
        self.log_path = log_path
        self.trs_ip = trs_ip

    def disconnect_session(self):
        """ Disconnects the SSH connection"""
        self.executor.run_ignoring_rc('rm -rf {}'.format(self.temp_dir))
        self.executor.disconnect()


class _SessionCmdBuilder(object):
    def __init__(self, btssm_builder, cl_builder, trs_builder):
        self.btssm_tool = btssm_builder
        self.cl_tool = cl_builder
        self.trs_tool = trs_builder


class _SessionScfc(object):
    def __init__(self, validator, fixer):
        self.validator = validator
        self.fixer = fixer
